import os, re, sys
from pathlib import Path
from PIL import Image
import pytesseract
import pandas as pd

IMG_DIR = Path('/app/workspace/dataset/img')
OUTPUT_XLSX = Path('/app/workspace/stat_ocr.xlsx')

# Date regex patterns (common formats)
DATE_PATTERNS = [
    r'(\d{4})[/-](\d{1,2})[/-](\d{1,2})',   # YYYY-MM-DD or YYYY/MM/DD
    r'(\d{1,2})[/-](\d{1,2})[/-](\d{4})',   # DD-MM-YYYY or DD/MM/YYYY
    r'(\d{1,2})[/-](\d{4})',                # MM-YYYY (fallback)
]

def normalize_date(text):
    for pat in DATE_PATTERNS:
        m = re.search(pat, text)
        if m:
            groups = m.groups()
            if len(groups) == 3:
                # Determine order by pattern index
                if pat.startswith('\\d{4}'):
                    y, mth, d = groups
                else:
                    d, mth, y = groups
                try:
                    y, mth, d = int(y), int(mth), int(d)
                    return f"{y:04d}-{mth:02d}-{d:02d}"
                except ValueError:
                    continue
            elif len(groups) == 2:
                # handle MM-YYYY
                mth, y = groups
                try:
                    y, mth = int(y), int(mth)
                    return f"{y:04d}-{mth:02d}-01"
                except ValueError:
                    continue
    return None

# Keywords for total amount extraction
TOTAL_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
