]
EXCLUDE_KEYWORDS = ["SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"]

amount_regex = re.compile(r'([\d,]+\.\d{2})')

def extract_total(text_lines):
    # Helper to find amount in a line
    def find_amount(line):
        for match in amount_regex.finditer(line.replace(' ', '')):
            amt = match.group(1).replace(',', '')
            try:
                float(amt)  # validate numeric
                return f"{float(amt):.2f}"
            except ValueError:
                continue
        return None

    # Iterate priority groups
    for group in TOTAL_KEYWORDS:
        for i, line in enumerate(text_lines):
            upper = line.upper()
            if any(kw in upper for kw in group):
                # Skip if any exclusion keyword present
                if any(exc in upper for exc in EXCLUDE_KEYWORDS):
                    continue
                # Try to find amount on same line
                amt = find_amount(line)
                if amt:
                    return amt
                # If not, look at next line(s) up to 2 lines ahead for amount not containing exclusion
                for offset in range(1, 3):
                    if i + offset < len(text_lines):
                        nxt = text_lines[i + offset]
                        nxt_up = nxt.upper()
                        if any(exc in nxt_up for exc in EXCLUDE_KEYWORDS):
                            continue
                        amt = find_amount(nxt)
                        if amt:
                            return amt
    return None

results = []
